-- Only actual parser/model controls advance this original input counter.
-- Display metadata is authenticated independently, not included in graph inputs.
CREATE TABLE knowledge_configuration_control_versions (
    knowledge_base_id TEXT PRIMARY KEY CHECK(length(trim(knowledge_base_id)) > 0),
    revision BIGINT NOT NULL CHECK(revision > 0)
);
INSERT INTO knowledge_configuration_control_versions(knowledge_base_id,revision) SELECT id,1 FROM knowledge_bases;
CREATE FUNCTION knowledge_configuration_control_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'UPDATE' THEN IF NOT (OLD.tenant_id IS DISTINCT FROM NEW.tenant_id OR OLD.type IS DISTINCT FROM NEW.type OR OLD.chunking_config::jsonb IS DISTINCT FROM NEW.chunking_config::jsonb OR OLD.image_processing_config::jsonb IS DISTINCT FROM NEW.image_processing_config::jsonb OR OLD.embedding_model_id IS DISTINCT FROM NEW.embedding_model_id OR OLD.summary_model_id IS DISTINCT FROM NEW.summary_model_id OR OLD.vlm_config::jsonb IS DISTINCT FROM NEW.vlm_config::jsonb OR OLD.asr_config::jsonb IS DISTINCT FROM NEW.asr_config::jsonb OR OLD.extract_config::jsonb IS DISTINCT FROM NEW.extract_config::jsonb OR OLD.faq_config::jsonb IS DISTINCT FROM NEW.faq_config::jsonb OR OLD.question_generation_config::jsonb IS DISTINCT FROM NEW.question_generation_config::jsonb OR OLD.auto_tag_config::jsonb IS DISTINCT FROM NEW.auto_tag_config::jsonb OR OLD.profile_config::jsonb IS DISTINCT FROM NEW.profile_config::jsonb OR OLD.wiki_config::jsonb IS DISTINCT FROM NEW.wiki_config::jsonb OR OLD.indexing_strategy::jsonb IS DISTINCT FROM NEW.indexing_strategy::jsonb OR OLD.deleted_at IS DISTINCT FROM NEW.deleted_at) THEN RETURN NEW; END IF; END IF; INSERT INTO knowledge_configuration_control_versions(knowledge_base_id,revision) VALUES(CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,1) ON CONFLICT(knowledge_base_id) DO UPDATE SET revision=knowledge_configuration_control_versions.revision+1; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE TRIGGER knowledge_configuration_control_version AFTER INSERT OR UPDATE OR DELETE ON knowledge_bases FOR EACH ROW EXECUTE FUNCTION knowledge_configuration_control_version();
